WITH base AS (SELECT *, UPPER(dept_name) dept_name_upper FROM departments WHERE dept_name IS NOT NULL) SELECT *, ROUND(budget / SUM(budget) OVER (PARTITION BY location), 4) budget_share, AVG(budget) OVER (PARTITION BY location, dept_name ORDER BY budget, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) budget_avg_6, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_budget, LEAD(budget, 2) OVER (PARTITION BY location ORDER BY budget, id) next_budget, NTILE(4) OVER (ORDER BY budget, id) budget_bucket FROM base;
